const body = $input.first().json.body || {};
const conversation = body.conversation || {};
const contact = conversation.contact_inbox?.contact || body.sender || {};

let rawPhone = contact.phone_number || body.sender?.phone_number || '';
let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
if (cleanPhone && !cleanPhone.startsWith('+') && !cleanPhone.startsWith('00')) {
    cleanPhone = '+' + cleanPhone;
}

const contactName = contact.name || body.sender?.name || 'Cliente';
const conversationId = String(conversation.id || body.conversation_id || '');
const messageContent = (body.content || '').trim();
const chatwootAccountId = String(body.account?.id || conversation.account_id || 1);
const inboxId = String(body.inbox?.id || conversation.inbox_id || 1);

const attachments = body.attachments || [];
const hasAudio = attachments.some(a => a.file_type === 'audio') || body.content_type === 'audio';
const isAudioOnly = (messageContent.length === 0 && (hasAudio || attachments.length > 0));

// Lista de números autorizados como Operador / Administrador
const operatorPhones = [
    '+584120000000',
    '+584245600261',
    '+584247416262'
].map(p => p.replace(/[^0-9+]/g, ''));

const isOperator = (cleanPhone.length > 5 && operatorPhones.some(op => cleanPhone === op || op.includes(cleanPhone) || cleanPhone.includes(op)));

return [{
    json: {
        phone: cleanPhone,
        contactName: contactName,
        conversationId: conversationId,
        messageContent: messageContent,
        chatwootAccountId: chatwootAccountId,
        inboxId: inboxId,
        isOperator: isOperator,
        isAudioOnly: isAudioOnly,
        rawEvent: body
    }
}];

