const getNodeSafe = (name) => {
    try { const n = $(name); if (n && n.first()) return n.first().json; } catch(e) {}
    return $input.first() ? $input.first().json : {};
};

const norm = getNodeSafe('Normalizar Datos');
const dbData = $input.first().json;

const products = dbData.products || [];
const categories = dbData.categories || [];
const settings = dbData.settings || [];
const dailyReport = dbData.daily_report || { orders_count: 0, total_usd: 0, total_cop: 0, total_ves: 0 };

let rateCop = 4000;
let rateVes = 40;
for (const s of settings) {
    if (s.key === 'rate_usd_cop') rateCop = Number(s.value) || 4000;
    if (s.key === 'rate_usd_ves') rateVes = Number(s.value) || 40;
}

let inventorySummary = '';
if (products.length > 0) {
    inventorySummary += '📦 *INVENTARIO EN BASE DE DATOS:*\n';
    products.forEach((p, idx) => {
        const basePrice = Number(p.price) || 0;
        let usd = basePrice, cop = basePrice, ves = basePrice;
        if (p.currency === 'USD') {
            cop = usd * rateCop;
            ves = usd * rateVes;
        } else if (p.currency === 'COP') {
            usd = cop / rateCop;
            ves = usd * rateVes;
        } else if (p.currency === 'VES') {
            usd = ves / rateVes;
            cop = usd * rateCop;
        }
        inventorySummary += `${idx + 1}) [${p.code}] *${p.name}* | Stock: ${p.stock} unid. | $${usd.toFixed(2)} USD / $${Math.round(cop).toLocaleString('es-CO')} COP / Bs. ${ves.toFixed(2)}\n`;
    });
} else {
    inventorySummary += '📦 *INVENTARIO:* (Sin productos registrados)\n';
}

const systemPrompt = `Eres el Asistente Administrativo de Control de Inventario y Operaciones del Sistema.
Atiendes al operador/administrador del negocio por WhatsApp y ejecutas acciones en la base de datos PostgreSQL.

======================================================================
TASAS DE CAMBIO VIGENTES:
• 1 USD = ${rateCop} COP
• 1 USD = ${rateVes} VES (Bolívares)

VENTAS DE HOY:
• Pedidos confirmados: ${dailyReport.orders_count}
• Total recaudado: $${Number(dailyReport.total_usd).toFixed(2)} USD | $${Number(dailyReport.total_cop).toLocaleString('es-CO')} COP | Bs. ${Number(dailyReport.total_ves).toFixed(2)}

======================================================================
ACCIONES DISPONIBLES (JSON estricto):
======================================================================
1. "get_inventory": Consultar productos y stock.
2. "update_stock": Cambiar o sumar stock de un producto.
   Data: {"code": "CAM-001", "name": "Gasa", "new_stock": 25} o {"code": "CAM-001", "add_stock": 10}
3. "update_price": Cambiar precio y/o moneda de un producto.
   Data: {"code": "CAM-001", "price": 12.50, "currency": "USD"}
4. "update_rates": Modificar tasas de cambio del sistema.
   Data: {"rate_usd_cop": 4100, "rate_usd_ves": 42.5}
5. "get_daily_sales": Ver reporte de ventas y pedidos de hoy.
6. "unknown": Responder consultas generales al operador.

ESTADO REAL DEL INVENTARIO:
${inventorySummary}

RESPONDE EXCLUSIVAMENTE UN OBJETO JSON:
{
  "action": "get_inventory" | "update_stock" | "update_price" | "update_rates" | "get_daily_sales" | "unknown",
  "data": { ... },
  "reply_message": "Respuesta ejecutiva, clara y con emojis para el administrador."
}`;

const geminiPayload = {
    contents: [
        {
            role: "user",
            parts: [{ text: norm.messageContent || '' }]
        }
    ],
    systemInstruction: {
        parts: [{ text: systemPrompt }]
    },
    generationConfig: {
        temperature: 0.1,
        responseMimeType: "application/json"
    }
};

return [{
    json: {
        geminiPayload: geminiPayload,
        inventorySummary: inventorySummary,
        phone: norm.phone,
        conversationId: norm.conversationId,
        chatwootAccountId: norm.chatwootAccountId
    }
}];

const getNodeSafe = (name) => {
    try { const n = $(name); if (n && n.first()) return n.first().json; } catch(e) {}
    return $input.first() ? $input.first().json : {};
};

const resp = $input.first().json;
const content = resp.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let parsed = {};
try {
    parsed = JSON.parse(content);
} catch (e) {
    parsed = { action: 'unknown', reply_message: content };
}

const prep = getNodeSafe('Operador: Preparar Prompt');
const norm = getNodeSafe('Normalizar Datos');

let sqlStatements = [];
const action = parsed.action || 'unknown';
const data = parsed.data || {};

sqlStatements.push(`
    INSERT INTO bot_operator_sessions (phone, conversation_id, chatwoot_account_id, updated_at)
    VALUES ('${norm.phone}', '${norm.conversationId}', '${norm.chatwootAccountId}', NOW())
    ON CONFLICT (phone) DO UPDATE
    SET conversation_id = EXCLUDED.conversation_id, chatwoot_account_id = EXCLUDED.chatwoot_account_id, updated_at = NOW();
`);

let customReply = parsed.reply_message || '';

if (action === 'get_inventory') {
    if (!customReply || customReply.includes('Operación realizada')) {
        customReply = `📋 *INVENTARIO ACTUAL EN SISTEMA:*\n\n${prep.inventorySummary || ''}`;
    }
} else if (action === 'update_stock') {
    const code = (data.code || '').replace(/'/g, "''");
    const name = (data.name || '').replace(/'/g, "''");
    if (data.new_stock !== undefined && !isNaN(Number(data.new_stock))) {
        const stockVal = Math.max(0, Number(data.new_stock));
        if (code) {
            sqlStatements.push(`UPDATE products SET stock = ${stockVal}, updated_at = NOW() WHERE code ILIKE '${code}';`);
        } else if (name) {
            sqlStatements.push(`UPDATE products SET stock = ${stockVal}, updated_at = NOW() WHERE name ILIKE '%${name}%';`);
        }
    } else if (data.add_stock !== undefined && !isNaN(Number(data.add_stock))) {
        const addVal = Number(data.add_stock);
        if (code) {
            sqlStatements.push(`UPDATE products SET stock = GREATEST(0, stock + ${addVal}), updated_at = NOW() WHERE code ILIKE '${code}';`);
        } else if (name) {
            sqlStatements.push(`UPDATE products SET stock = GREATEST(0, stock + ${addVal}), updated_at = NOW() WHERE name ILIKE '%${name}%';`);
        }
    }
} else if (action === 'update_price') {
    const code = (data.code || '').replace(/'/g, "''");
    const name = (data.name || '').replace(/'/g, "''");
    const priceVal = Number(data.price);
    const currencyVal = (data.currency || 'USD').toUpperCase().replace(/'/g, "''");
    if (!isNaN(priceVal) && priceVal >= 0) {
        if (code) {
            sqlStatements.push(`UPDATE products SET price = ${priceVal}, currency = '${currencyVal}', updated_at = NOW() WHERE code ILIKE '${code}';`);
        } else if (name) {
            sqlStatements.push(`UPDATE products SET price = ${priceVal}, currency = '${currencyVal}', updated_at = NOW() WHERE name ILIKE '%${name}%';`);
        }
    }
} else if (action === 'update_rates') {
    if (data.rate_usd_cop) {
        const rCop = Number(data.rate_usd_cop);
        if (rCop > 0) sqlStatements.push(`INSERT INTO app_settings (key, value) VALUES ('rate_usd_cop', '${rCop}') ON CONFLICT (key) DO UPDATE SET value = '${rCop}';`);
    }
    if (data.rate_usd_ves) {
        const rVes = Number(data.rate_usd_ves);
        if (rVes > 0) sqlStatements.push(`INSERT INTO app_settings (key, value) VALUES ('rate_usd_ves', '${rVes}') ON CONFLICT (key) DO UPDATE SET value = '${rVes}';`);
    }
}

const finalQuery = sqlStatements.join('; ');

return [{
    json: {
        sqlQuery: finalQuery,
        replyMessage: customReply || '✅ ¡Operación ejecutada con éxito en PostgreSQL!',
        conversationId: norm.conversationId,
        chatwootAccountId: norm.chatwootAccountId
    }
}];

const getNodeSafe = (name) => {
