    cartSummaryText = `CARRITO EN CONSTRUCCIÓN:\n${lines.join('\n')}\nTotal Acumulado: $${Number(currentOrder.total_usd).toFixed(2)} USD | $${Number(currentOrder.total_cop).toLocaleString('es-CO')} COP | Bs. ${Number(currentOrder.total_ves).toFixed(2)}`;
}

