const getNodeSafe = (name) => {
    try { const n = $(name); if (n && n.first()) return n.first().json; } catch(e) {}
    return $input.first() ? $input.first().json : {};
};

const resp = $input.first().json;
const content = resp.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const prep = getNodeSafe('Cliente: Preparar Prompt');
const norm = getNodeSafe('Normalizar Datos');

let parsed = { reply_text: '¡Hola! ¿En qué producto te puedo asesorar hoy? 😊', order_action: 'inquiry', items_to_add: [] };
try {
    parsed = JSON.parse(content);
} catch (e) {
    parsed.reply_text = content;
}

const action = parsed.order_action || 'inquiry';
const itemsToAdd = Array.isArray(parsed.items_to_add) ? parsed.items_to_add : [];
const convId = norm.conversationId || prep.conversationId;
const phone = norm.phone || prep.phone;
const contactName = (norm.contactName || prep.contactName || 'Cliente').replace(/'/g, "''");

const rateCop = Number(prep.rateCop) || 4000;
const rateVes = Number(prep.rateVes) || 40;

let orderSql = 'SELECT 1;';
let currentOrder = prep.currentOrder || {};
let runningTotalUsd = Number(currentOrder.total_usd) || 0;
let runningTotalCop = Number(currentOrder.total_cop) || 0;
let runningTotalVes = Number(currentOrder.total_ves) || 0;

let stockUpdateQueries = [];

if (action === 'add_items' && itemsToAdd.length > 0) {
    let inserts = [];
    let addedUsd = 0;

    for (const item of itemsToAdd) {
        if (!item || !item.product_name) continue;

        const prodName = (item.product_name || '').replace(/'/g, "''");
        const prodCode = (item.code || '').replace(/'/g, "''");
        const qty = Math.max(1, Number(item.quantity) || 1);
        const unitPriceUsd = Number(item.unit_price_usd) || (Number(item.unit_price_cop) ? Number(item.unit_price_cop)/rateCop : 0);
        const subUsd = unitPriceUsd * qty;
        const subCop = subUsd * rateCop;
        const subVes = subUsd * rateVes;

        addedUsd += subUsd;
        const prodIdVal = item.product_id ? Number(item.product_id) : 'NULL';

        inserts.push(`
            INSERT INTO bot_order_items (order_id, product_id, product_name, code, quantity, unit_price, currency, subtotal_usd, subtotal_cop, subtotal_ves)
            SELECT id, ${prodIdVal}, '${prodName}', '${prodCode}', ${qty}, ${unitPriceUsd}, 'USD', ${subUsd}, ${subCop}, ${subVes}
            FROM bot_orders WHERE conversation_id = '${convId}' AND status = 'building' LIMIT 1;
        `);
    }

    runningTotalUsd += addedUsd;
    runningTotalCop = runningTotalUsd * rateCop;
    runningTotalVes = runningTotalUsd * rateVes;

    orderSql = `
    INSERT INTO bot_orders (conversation_id, phone, contact_name, status, total_usd, total_cop, total_ves)
    SELECT '${convId}', '${phone}', '${contactName}', 'building', ${runningTotalUsd}, ${runningTotalCop}, ${runningTotalVes}
    WHERE NOT EXISTS (SELECT 1 FROM bot_orders WHERE conversation_id = '${convId}' AND status = 'building');

    ${inserts.join('\n')}

    UPDATE bot_orders
    SET 
      total_usd = ${runningTotalUsd},
      total_cop = ${runningTotalCop},
      total_ves = ${runningTotalVes},
      updated_at = NOW()
    WHERE conversation_id = '${convId}' AND status = 'building';
    `;
} else if (action === 'remove_item') {
    const itemTarget = (parsed.remove_target || '').replace(/'/g, "''");
    orderSql = `
    DELETE FROM bot_order_items
    WHERE id = (
        SELECT id FROM bot_order_items
        WHERE order_id = (SELECT id FROM bot_orders WHERE conversation_id = '${convId}' AND status = 'building' LIMIT 1)
          AND (product_name ILIKE '%${itemTarget}%' OR code ILIKE '%${itemTarget}%')
        LIMIT 1
    );

    UPDATE bot_orders o
    SET 
      total_usd = COALESCE((SELECT SUM(subtotal_usd) FROM bot_order_items WHERE order_id = o.id), 0),
      total_cop = COALESCE((SELECT SUM(subtotal_cop) FROM bot_order_items WHERE order_id = o.id), 0),
      total_ves = COALESCE((SELECT SUM(subtotal_ves) FROM bot_order_items WHERE order_id = o.id), 0),
      updated_at = NOW()
    WHERE o.conversation_id = '${convId}' AND o.status = 'building';
    `;
} else if (action === 'confirm_order') {
    const orderSum = parsed.order_summary || {};
    const finalUsd = Number(orderSum.total_usd) || runningTotalUsd;
    const finalCop = finalUsd * rateCop;
    const finalVes = finalUsd * rateVes;
    const deliveryAddr = (orderSum.delivery_address || 'Entrega a acordar').replace(/'/g, "''");
    const payMethod = (orderSum.payment_method || 'Por definir').replace(/'/g, "''");

    // Descontar inventario automáticamente en PostgreSQL al confirmar el pedido
    stockUpdateQueries.push(`
      UPDATE products p
      SET stock = GREATEST(0, p.stock - oi.quantity),
          updated_at = NOW()
      FROM bot_order_items oi
      JOIN bot_orders o ON o.id = oi.order_id
      WHERE o.conversation_id = '${convId}' AND o.status = 'building'
        AND (p.id = oi.product_id OR (oi.code IS NOT NULL AND p.code = oi.code));
    `);

    orderSql = `
    UPDATE bot_orders
    SET status = 'confirmed',
        total_usd = CASE WHEN ${finalUsd} > 0 THEN ${finalUsd} ELSE total_usd END,
        total_cop = CASE WHEN ${finalUsd} > 0 THEN ${finalCop} ELSE total_cop END,
        total_ves = CASE WHEN ${finalUsd} > 0 THEN ${finalVes} ELSE total_ves END,
        delivery_address = '${deliveryAddr}',
        payment_method = '${payMethod}',
        confirmed_at = NOW(),
        updated_at = NOW()
    WHERE conversation_id = '${convId}' AND status = 'building';
    `;
} else if (action === 'clear_order') {
    orderSql = `
    UPDATE bot_orders
    SET status = 'cancelled', updated_at = NOW()
    WHERE conversation_id = '${convId}' AND status = 'building';
    `;
}

const userMsgClean = (norm.messageContent || '').replace(/'/g, "''");
const replyMsgClean = (parsed.reply_text || '').replace(/'/g, "''");

const historySql = `
INSERT INTO bot_conversation_history (conversation_id, phone, role, content)
VALUES 
  ('${convId}', '${phone}', 'user', '${userMsgClean}'),
  ('${convId}', '${phone}', 'assistant', '${replyMsgClean}');
`;

const fullSql = `${stockUpdateQueries.join('; ')}; ${orderSql}; ${historySql}`;

const orderSum = parsed.order_summary || {};
let itemsListStr = orderSum.items_detail || '';

if (!itemsListStr) {
    const items = currentOrder.items || [];
    if (items.length > 0) {
        itemsListStr = items.map(i => `• ${i.quantity}x *${i.product_name}* [${i.code || ''}] — $${Number(i.subtotal_usd).toFixed(2)} USD`).join('\n');
    } else {
        itemsListStr = '• Pedido confirmado por el cliente';
    }
}

const confirmedUsd = Number(orderSum.total_usd) || runningTotalUsd;
const confirmedCop = confirmedUsd * rateCop;
const confirmedVes = confirmedUsd * rateVes;
const deliveryAddr = orderSum.delivery_address || 'Entrega a acordar';
const payMethod = orderSum.payment_method || 'Por definir';

